WITH lines AS (SELECT id, log_ts, latency_ms, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) e AS attr_key, attr_value) SELECT DATE_TRUNC('DAY', log_ts) AS activity_day, COUNT(*) FILTER (WHERE attr_key = 'trace') AS trace_rows, SUM(status_code) FILTER (WHERE attr_key = 'region') AS region_total_status_code, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS span_minutes, AVG(status_code) AS avg_status_code, PERCENTILE_APPROX(status_code, 0.95) AS status_code_p95, SUM(CASE WHEN attr_key = 'region' THEN status_code ELSE 0 END) AS region_status_code FROM lines GROUP BY DATE_TRUNC('DAY', log_ts);
